#!/usr/bin/env python3
"""Court floor tiles, far-side backdrops and the ball for Road Trip Hoops (original pixel art, generated by script;
no downloaded assets). Same look as the owner-approved player style sample v1: 4 tones per colour, light from the
upper left, warm lights and cool shadows.

Outputs (all opaque except the ball):
  assets/courts/gym_floor.png          64 x 64   seamless maple boards (boards run along the court length)
  assets/courts/blacktop_floor.png     64 x 64   seamless asphalt
  assets/courts/gym_backdrop.png      384 x 100  bleachers with a pixel crowd, wall banners, scoreboard; tiles in x
  assets/courts/blacktop_backdrop.png 384 x 100  chain-link fence, street, parked cars, buildings, trees; tiles in x
  assets/ball/ball.png                 64 x 16   4 spin frames of 16 x 16 (hframes = 4), ball 11 px across
  assets/courts/<look>_floor.png       64 x 64   Phase 6 city looks (P6-A2), same conventions as above:
  assets/courts/<look>_backdrop.png   384 x 100    barn (Hometown driveway, cornfield), rooftop (Chicago lakefront,
                                                   skyline, flags), soul_gym (Memphis old-school gym, packed crowd),
                                                   bayou (New Orleans, cypress, string lights), mountain (Denver,
                                                   peaks), rain_park (Seattle, wet sheen, rain), beach (Los Angeles,
                                                   sand, boardwalk), cage (New York, city blocks behind a tall fence)
  docs/art/courts_preview_v2.png      the city looks for the owner: the game's own 1280 x 720 screenshot of each, its
                                       whole backdrop and its floor tile 3 x 3 (needs --shots DIR, below)
  docs/art/courts_preview_v1.png      preview: both looks composed in the 3/4 view as the game frames it, plus the
                                       whole backdrops (not exported)
  docs/art/courts_tiles_4x4.png       each floor tile repeated 4 x 4 (seam check, not exported)

How the game should draw them (texel = one pixel of these images):
  - Everything is drawn in the view's canvas at TEXEL_PX (2) canvas pixels per texel, like the 2x player sprites,
    in both directions. The floor tiles are already drawn as seen in the 3/4 view (foreshortened boards), so tile
    them on the projected floor with a uniform 2x scale (one tile = 128 x 128 canvas px); don't stretch them by
    1/TILT_Y. The ANGLED floor with PERSPECTIVE 0 is a plain screen rectangle, so a tiled draw_texture_rect works.
  - Backdrops: bottom row on the far edge of the apron (BACKDROP_BOTTOM_FT behind the far sideline), repeated left
    and right; 200 canvas px tall, which covers the room above the far sideline at the ANGLED zoom (1280x720 and
    1280x800). If more shows above, fill with the top-left pixel's colour (wall / sky).
  - Ball: 2x like the players (22 canvas px across, about today's size). Frames turn the ball forward (top toward
    +x on screen); play them faster for a fast ball, mirror (flip_h) for a ball moving left. The highlight stays at
    the upper left in every frame.

Usage:  python3 tools/art/make_courts.py                  all textures, the v1 preview and the tile test
        python3 tools/art/make_courts.py --shots DIR      also courts_preview_v2.png from DIR/<look>.png, the game's
                                                          screenshots: for each look,  -- --court <look> --shots
                                                          (xvfb, see CLAUDE.md), then copy /tmp/hoops_1800.png
        python3 tools/art/make_courts.py --print-looks    prints the city looks' court_looks.gd entries (colours for
                                                          the lines, paint, hoop; CITY_LOOKS below) as GDScript
Needs:  Pillow, numpy
"""
import math
import os
import random
import sys

import numpy as np
from PIL import Image, ImageDraw

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import pixel3d as P  # noqa: E402  (palette helpers, LIGHT, digits)

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))
COURTS = os.path.join(ROOT, "assets", "courts")
BALLS = os.path.join(ROOT, "assets", "ball")
PREVIEW = os.path.join(ROOT, "docs", "art", "courts_preview_v1.png")
PREVIEW_V2 = os.path.join(ROOT, "docs", "art", "courts_preview_v2.png")
TILES_TEST = os.path.join(ROOT, "docs", "art", "courts_tiles_4x4.png")

TEXEL_PX = 2              # canvas px per texel (same as PLAYER_SCALE)
TILE = 64
BD_W, BD_H = 384, 100     # backdrop size (texels)
BACKDROP_BOTTOM_FT = 4.0  # recommended gap between the far sideline and the backdrop's bottom row (apron)

H = P.hexc


def pal(*hexes):
    return [H(h) for h in hexes]


def mix(a, b, t):
    return tuple(int(round(a[k] * (1 - t) + b[k] * t)) for k in range(3))


class Pix:
    """An RGB texel canvas with wrap-around in x (backdrops and tiles repeat left-right)."""

    def __init__(self, w, h, fill, wrap_y=False):
        self.w, self.h, self.wrap_y = w, h, wrap_y
        self.a = np.zeros((h, w, 3), np.uint8)
        self.a[:, :] = fill

    def put(self, x, y, c):
        x = int(x) % self.w
        y = int(y)
        if self.wrap_y:
            y %= self.h
        if 0 <= y < self.h:
            self.a[y, x] = c

    def get(self, x, y):
        return tuple(int(v) for v in self.a[int(y) % self.h if self.wrap_y else int(y), int(x) % self.w])

    def rect(self, x0, y0, x1, y1, c):  # inclusive
        for y in range(int(y0), int(y1) + 1):
            for x in range(int(x0), int(x1) + 1):
                self.put(x, y, c)

    def blend(self, x, y, c, t):
        y = int(y)
        if 0 <= y < self.h:
            self.put(x, y, mix(self.get(x, y), c, t))

    def image(self):
        return Image.fromarray(self.a.copy(), "RGB")


def periodic_noise(w, h, cells, rnd, octaves=3):
    """Smooth value noise that wraps in both directions (for seamless tiles)."""
    out = np.zeros((h, w))
    amp, total = 1.0, 0.0
    for o in range(octaves):
        n = cells * (2 ** o)
        g = np.array([[rnd.random() for _ in range(n)] for _ in range(n)])
        ys, xs = np.mgrid[0:h, 0:w]
        fx, fy = xs * n / w, ys * n / h
        x0, y0 = np.floor(fx).astype(int), np.floor(fy).astype(int)
        tx, ty = fx - x0, fy - y0
        tx, ty = tx * tx * (3 - 2 * tx), ty * ty * (3 - 2 * ty)
        x1, y1 = (x0 + 1) % n, (y0 + 1) % n
        x0, y0 = x0 % n, y0 % n
        v = (g[y0, x0] * (1 - tx) + g[y0, x1] * tx) * (1 - ty) + (g[y1, x0] * (1 - tx) + g[y1, x1] * tx) * ty
        out += amp * v
        total += amp
        amp *= 0.5
    return out / total


# ----------------------------------------------------------------------------- floor tiles

WOOD = pal("#e2ab70", "#d9a066", "#cf955c", "#c68c55")      # board tones (light .. dark), from the sample floor
WOOD_SEAM = H("#a86f3e")
WOOD_GRAIN = H("#bf8450")
WOOD_KNOT = H("#9c6436")


def gym_floor(seed=11):
    """Maple boards seen from the sideline: 3-texel boards + a 1-texel seam, random lengths, all wrapping."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, WOOD[1], wrap_y=True)
    rows = TILE // 4
    for r in range(rows):
        y = r * 4
        # board joints: 2 or 3 per row at random places, at least 14 texels apart (wraps around)
        while True:
            n = rnd.choice((2, 2, 3))
            js = sorted(rnd.randrange(TILE) for _ in range(n))
            gaps = [(js[(k + 1) % n] - js[k]) % TILE for k in range(n)]
            if min(gaps) >= 14:
                break
        for k in range(n):
            x0, L = js[k], gaps[k]
            tone = rnd.choice((0, 1, 1, 2, 2, 3))
            base = WOOD[tone]
            for dx in range(L):
                x = x0 + dx
                for dy in range(3):
                    c = base
                    if dy == 0:
                        c = mix(base, (255, 236, 200), 0.10)     # lit top edge of the board
                    if dx == L - 1:
                        c = mix(base, WOOD_SEAM, 0.55)           # end joint
                    px.put(x, y + dy, c)
            # grain: short darker streaks along the board
            for _ in range(max(1, L // 10)):
                gx = x0 + rnd.randint(1, max(1, L - 7))
                gy = y + rnd.randint(1, 2)
                for q in range(rnd.randint(3, 6)):
                    if (gx + q - x0) % TILE < L - 1:
                        px.put(gx + q, gy, mix(base, WOOD_GRAIN, 0.55))
            if rnd.random() < 0.12 and L > 12:                   # an occasional knot
                kx = x0 + rnd.randint(3, L - 5)
                px.put(kx, y + 1, WOOD_KNOT)
                px.put(kx + 1, y + 1, mix(base, WOOD_KNOT, 0.5))
        for x in range(TILE):
            px.put(x, y + 3, WOOD_SEAM)
    return px.image()


ASPHALT = pal("#54575f", "#4c4f57", "#45484f", "#3d4047")
ASPHALT_STONE = pal("#7c7d82", "#6a6b72")
ASPHALT_PIT = H("#2a2b31")


def blacktop_floor(seed=5):
    """Worn asphalt: soft tonal blotches quantized to 4 tones, light aggregate speckles, dark pits."""
    rnd = random.Random(seed)
    n = periodic_noise(TILE, TILE, 4, rnd, octaves=3)
    fine = periodic_noise(TILE, TILE, 16, rnd, octaves=1)
    v = 0.75 * n + 0.25 * fine
    v = (v - v.min()) / (v.max() - v.min())
    px = Pix(TILE, TILE, ASPHALT[1], wrap_y=True)
    for y in range(TILE):
        for x in range(TILE):
            t = v[y, x]
            k = 0 if t > 0.80 else (1 if t > 0.48 else (2 if t > 0.2 else 3))
            px.put(x, y, ASPHALT[k])
    # speckles (aggregate): mostly single light texels, some 2-texel stones with a shadow under them
    for _ in range(110):
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        if rnd.random() < 0.25:
            px.put(x, y, ASPHALT_STONE[0])
            px.put(x + 1, y, ASPHALT_STONE[1])
            px.put(x, y + 1, ASPHALT[3])
            px.put(x + 1, y + 1, ASPHALT[3])
        else:
            px.put(x, y, ASPHALT_STONE[1] if rnd.random() < 0.7 else ASPHALT_STONE[0])
    for _ in range(40):
        px.put(rnd.randrange(TILE), rnd.randrange(TILE), ASPHALT_PIT)
    return px.image()


# ----------------------------------------------------------------------------- shared backdrop bits

SKIN = [pal(*v) for v in P.SKINS.values()] + [pal("#c28058", "#985c3a", "#6c3c2a", "#442222")]
HAIR = pal("#2a2024", "#19121a", "#7a4c30", "#55321f", "#9a4a26", "#d8c088", "#121019")
SHIRTS = [pal("#ff7a6a", "#d8283a", "#951833", "#5a0e2a"), pal("#78b8ff", "#2f74e0", "#1f479e", "#172a66"),
          pal("#ffffff", "#e4eaf4", "#a9b6d4", "#6c7aa4"), pal("#5c5c72", "#34343f", "#1f1e2a", "#121019"),
          pal("#ffe080", "#f0b830", "#b07818", "#6c4410"), pal("#9be08a", "#4fae4a", "#2e7a3a", "#1a4a2a"),
          pal("#d8a0ff", "#9a5ad0", "#683a9a", "#3e2266"), pal("#ffc08a", "#f08a3a", "#b0561e", "#6c3012"),
          pal("#9ae0e0", "#3aa6b0", "#24707e", "#16444e")]
DIGITS = P.DIGITS


def digit(px, d, x, y, c, shadow=None):
    for gy, row in enumerate(DIGITS[d]):
        for gx, ch in enumerate(row):
            if ch == "1":
                if shadow:
                    px.put(x + gx + 1, y + gy + 1, shadow)
                px.put(x + gx, y + gy, c)


def number(px, s, x, y, c, shadow=None):
    for k, ch in enumerate(s):
        digit(px, int(ch), x + 4 * k, y, c, shadow)


def fade(img, toward, t):
    """Push a backdrop back in space: blend toward a haze colour (players must pop against it)."""
    a = np.asarray(img).astype(float)
    a = a * (1 - t) + np.array(toward, float) * t
    return Image.fromarray(np.clip(a + 0.5, 0, 255).astype(np.uint8), "RGB")


# ----------------------------------------------------------------------------- gym backdrop

WALL = pal("#4c4a6a", "#3e3c5a", "#33314c", "#28263c")          # painted block wall, cool purple-grey
BLEACH = pal("#e8c690", "#c99e64", "#9c7444", "#6e4e2e")        # wooden bleacher boards
RISER = pal("#5a4a52", "#463a42", "#352c34", "#261e26")         # dark riser faces between tiers
PAD = pal("#4a64b0", "#263c84", "#18245a", "#0e1236")           # navy padded rail along the court
BANNER_COLS = [pal("#ff7a6a", "#d8283a", "#951833", "#5a0e2a"), pal("#78b8ff", "#2f74e0", "#1f479e", "#172a66"),
               pal("#ffe080", "#f0b830", "#b07818", "#6c4410"), pal("#9be08a", "#4fae4a", "#2e7a3a", "#1a4a2a"),
               pal("#ffffff", "#e4eaf4", "#a9b6d4", "#6c7aa4")]
TIERS = 4
TIER_H = 9                 # texels per bleacher tier (seat + riser)
BLEACHER_TOP = BD_H - 8 - TIERS * TIER_H   # first (highest) tier's top row


def person(px, x, y, rnd, tier, standing=False, arms_up=False):
    """One spectator from the bleachers: x = left of the 5-wide body, y = top of the head (3/4 view, seated)."""
    sk = rnd.choice(SKIN)
    sh = rnd.choice(SHIRTS)
    hair = rnd.choice(HAIR)
    hair_kind = rnd.choice(("short", "short", "bald", "cap", "puff"))
    # body (shirt): 5 wide, 4 tall, light from the upper left
    by = y + 4
    for dy in range(4 + (2 if standing else 0)):
        for dx in range(5):
            k = 1
            if dx == 0 or dy == 0:
                k = 0 if (dx == 0 and dy < 2) or dy == 0 and dx < 3 else 1
            if dx == 4:
                k = 2
            if dy >= 3:
                k = max(k, 2)
            if (dx == 0 or dx == 4) and dy == 0:
                continue  # rounded shoulders
            px.put(x + dx, by + dy, sh[k])
    # head: 3 wide, 4 tall, centred, highlight top-left
    hx = x + 1
    for dy in range(4):
        for dx in range(3):
            k = 1
            if dx == 0 and dy < 2:
                k = 0
            if dx == 2 or dy == 3:
                k = 2
            px.put(hx + dx, y + dy, sk[k])
    px.put(hx + 1, y + 2, sk[3]) if rnd.random() < 0.3 else None   # a mouth (some cheer)
    if hair_kind == "short":
        for dx in range(3):
            px.put(hx + dx, y, mix(hair, (255, 255, 255), 0.15) if dx < 2 else hair)
        px.put(hx + 2, y + 1, hair)
    elif hair_kind == "cap":
        cc = rnd.choice(SHIRTS)
        for dx in range(-1, 3):
            px.put(hx + dx, y, cc[1] if dx < 2 else cc[2])
    elif hair_kind == "puff":
        for dx in range(-1, 4):
            px.put(hx + dx, y - 1 if 0 <= dx <= 2 else y, hair)
        px.put(hx, y, hair)
        px.put(hx + 1, y, hair)
        px.put(hx + 2, y, hair)
    if arms_up:
        side = rnd.choice((0, 4))
        for dy in range(1, 4):
            px.put(x + side, y + 4 - dy, sh[1] if dy == 1 else sk[1 if side == 0 else 2])
        if rnd.random() < 0.6:
            other = 4 - side
            for dy in range(1, 4):
                px.put(x + other, y + 4 - dy, sh[1] if dy == 1 else sk[1 if other == 0 else 2])


def gym_backdrop(seed=3):
    rnd = random.Random(seed)
    px = Pix(BD_W, BD_H, WALL[1])
    # wall: horizontal block courses, darker toward the top (lights hang low over the court)
    for y in range(BLEACHER_TOP + 2):
        for x in range(BD_W):
            k = 1 if y > 22 else 2
            if y % 6 == 5:
                k = min(3, k + 1)                       # mortar line
            elif (x + (3 if (y // 6) % 2 else 0)) % 12 == 0:
                k = min(3, k + 1)                       # block joint
            px.put(x, y, WALL[k])
    # top: a dark band with the ceiling lights
    px.rect(0, 0, BD_W - 1, 3, WALL[3])
    for x in range(8, BD_W, 32):
        px.rect(x, 2, x + 5, 3, H("#fff4d0"))
        px.rect(x + 1, 4, x + 4, 4, mix(WALL[1], H("#fff4d0"), 0.35))
    # banners: hanging pennants with a year, and a scoreboard in the middle (all generic, no names)
    years = ["1987", "1994", "2003", "2011", "1979", "2016"]
    slots = [12, 70, 128, 236, 294, 352]
    for k, bx in enumerate(slots):
        c = BANNER_COLS[k % len(BANNER_COLS)]
        top, w, hgt = 27, 24, 20
        for y in range(top, top + hgt):
            for x in range(bx, bx + w):
                kk = 1
                if x == bx or y == top:
                    kk = 0
                if x == bx + w - 1:
                    kk = 2
                px.put(x, y, c[kk])
        # pennant tail
        for d in range(6):
            for x in range(bx + d, bx + w - d):
                px.put(x, top + hgt + d, c[1] if x < bx + w - 1 - d else c[2])
        ink = BANNER_COLS[(k + 2) % len(BANNER_COLS)][1] if k % 5 != 4 else H("#d8283a")
        if k % len(BANNER_COLS) == 4:
            ink = H("#1f479e")
        # star
        cx, cy = bx + w // 2, top + 6
        for dy, row in enumerate(("..X..", "XXXXX", ".XXX.", ".X.X.", "X...X")):
            for dx, ch in enumerate(row):
                if ch == "X":
                    px.put(cx - 2 + dx, cy - 3 + dy, ink)
        number(px, years[k], bx + 4, top + 11, ink)
        # hanging wire
        px.put(bx + 3, top - 1, WALL[3])
        px.put(bx + w - 4, top - 1, WALL[3])
    # scoreboard
    sx0, sx1, sy0, sy1 = 176, 224, 26, 50
    px.rect(sx0, sy0, sx1, sy1, H("#1a1820"))
    px.rect(sx0, sy0, sx1, sy0, H("#5a566e"))
    px.rect(sx0, sy0, sx0, sy1, H("#5a566e"))
    px.rect(sx1, sy0, sx1, sy1, H("#0c0a10"))
    px.rect(sx0, sy1, sx1, sy1, H("#0c0a10"))
    px.rect(sx0 + 3, sy0 + 3, sx0 + 20, sy0 + 12, H("#2a0e0e"))
    px.rect(sx1 - 20, sy0 + 3, sx1 - 3, sy0 + 12, H("#2a0e0e"))
    number(px, "21", sx0 + 5, sy0 + 5, H("#ffb030"))
    number(px, "19", sx1 - 18, sy0 + 5, H("#ffb030"))
    px.rect(sx0 + 3, sy0 + 15, sx0 + 8, sy0 + 17, H("#4fae4a"))
    px.rect(sx1 - 8, sy0 + 15, sx1 - 3, sy0 + 17, H("#d8283a"))
    number(px, "24", sx0 + 20, sy0 + 15, H("#ff5a3a"))
    # bleachers: tiers from the top (back, smaller and darker) to the bottom (front)
    for t in range(TIERS):
        y0 = BLEACHER_TOP + t * TIER_H
        # riser face (shadowed, behind the people of this tier)
        px.rect(0, y0, BD_W - 1, y0 + TIER_H - 4, RISER[2 if t < 3 else 1])
        px.rect(0, y0, BD_W - 1, y0, RISER[3])
        # seat board: lit top, front edge
        px.rect(0, y0 + TIER_H - 3, BD_W - 1, y0 + TIER_H - 3, BLEACH[0])
        px.rect(0, y0 + TIER_H - 2, BD_W - 1, y0 + TIER_H - 2, BLEACH[1])
        px.rect(0, y0 + TIER_H - 1, BD_W - 1, y0 + TIER_H - 1, BLEACH[3])
        # aisles: steps every 128 texels
        for ax in (60, 188, 316):
            px.rect(ax, y0, ax + 7, y0 + TIER_H - 4, RISER[1])
            px.rect(ax, y0 + TIER_H - 3, ax + 7, y0 + TIER_H - 3, H("#f0d8a8"))
            px.put(ax + 7, y0 + TIER_H - 2, BLEACH[2])
        # crowd: seated on the seat of this tier, heads poking above the riser
        x = rnd.randint(0, 4)
        density = 0.93 - 0.03 * t
        while x < BD_W:
            if any(ax - 5 <= x % BD_W <= ax + 8 for ax in (60, 188, 316)):
                x += 2
                continue
            if rnd.random() < density:
                standing = rnd.random() < 0.10
                person(px, x, y0 + TIER_H - 10 - (2 if standing else 0), rnd, t, standing,
                       arms_up=rnd.random() < 0.16)
            x += rnd.choice((5, 6, 6, 6, 7))
    # front: a padded rail along the court and its shadow line on the floor
    fy = BD_H - 8
    px.rect(0, fy, BD_W - 1, BD_H - 1, PAD[1])
    px.rect(0, fy, BD_W - 1, fy, PAD[0])
    px.rect(0, BD_H - 2, BD_W - 1, BD_H - 1, PAD[2])
    px.rect(0, BD_H - 1, BD_W - 1, BD_H - 1, PAD[3])
    for x in range(0, BD_W, 48):          # pad seams
        px.rect(x, fy + 1, x, BD_H - 2, PAD[2])
        px.put(x + 1, fy + 1, PAD[0])
    img = px.image()
    # keep the backdrop behind the players: soft haze toward the wall colour, stronger high up
    a = np.asarray(img).astype(float)
    haze = np.array(H("#26243a"), float)
    for y in range(BD_H):
        t = 0.30 - 0.18 * (y / (BD_H - 1))
        a[y] = a[y] * (1 - t) + haze * t
    return Image.fromarray(np.clip(a + 0.5, 0, 255).astype(np.uint8), "RGB")


# ----------------------------------------------------------------------------- blacktop backdrop

SKY = pal("#9fd2f0", "#b8e0f4", "#d0ecf6", "#e6f4f4")         # top .. horizon
BRICK = [pal("#c0684c", "#a4523c", "#843e30", "#5e2a24"), pal("#d8a070", "#bc8456", "#946240", "#6a4430"),
         pal("#8a8494", "#6e6878", "#56505e", "#3e3846"), pal("#b05a5a", "#8e4446", "#6c3036", "#4a2028")]
GLASS = pal("#a8d0e8", "#6e9cc0", "#4a6e94", "#2e4466")
LEAF = pal("#8cc85a", "#5aa042", "#3a7634", "#244c26")
TRUNK = pal("#8a6040", "#6a4630", "#4c3022", "#30201a")
CONCRETE = pal("#cfcac0", "#b8b2a6", "#9c968a", "#7c766c")
ROAD = pal("#62646c", "#55575f", "#4a4c54", "#3e4048")
FENCE = pal("#e8ecf0", "#b4bcc6", "#8a94a0", "#5e6874")
CARS = [pal("#ff9a7a", "#e0503a", "#a83224", "#6c1e18"), pal("#9ad0ff", "#3a86d0", "#245c9a", "#163a66"),
        pal("#fff0a0", "#e8c440", "#b08a20", "#6c5410"), pal("#e8ecf0", "#c0c6d0", "#8a94a0", "#5e6874")]

SIDEWALK_Y = 66          # far sidewalk top (in front of the buildings)
ROAD_Y = 71              # street top
ROAD_Y1 = 85             # street bottom (near curb)
GROUND_Y = 90            # strip of ground between the curb and the fence foot
FENCE_TOP = 38           # fence top rail (fence about 12 ft)


def building(px, x0, w, top, c, rnd, kind):
    """A row building: brick front lit from the left, window grid, cornice, maybe a fire escape or awning."""
    for y in range(top, SIDEWALK_Y):
        for x in range(x0, x0 + w):
            k = 1
            if (y - top) % 3 == 2 and kind != "stucco":
                k = 2                                        # brick courses
            if x == x0:
                k = 0
            if x >= x0 + w - 2:
                k = 2
            px.put(x, y, c[k])
    # cornice
    px.rect(x0 - 1, top, x0 + w, top + 1, c[0])
    px.rect(x0 - 1, top + 2, x0 + w, top + 2, c[3])
    # windows
    wy = top + 5
    while wy + 6 < SIDEWALK_Y - 6:
        wx = x0 + 3
        while wx + 4 < x0 + w - 2:
            lit = rnd.random() < 0.18
            for yy in range(5):
                for xx in range(4):
                    g = GLASS[1] if xx > yy - 1 else GLASS[2]
                    if lit:
                        g = H("#ffe7a0") if xx > 0 else H("#e8c070")
                    px.put(wx + xx, wy + yy, g)
            px.put(wx, wy, GLASS[0] if not lit else H("#fff4d0"))
            px.rect(wx - 1, wy + 5, wx + 4, wy + 5, CONCRETE[1])      # sill
            px.rect(wx + 4, wy, wx + 4, wy + 4, c[3])                  # reveal shadow
            wx += 8
        wy += 9
    # ground floor: a door and a shop window or awning
    gy = SIDEWALK_Y - 8
    px.rect(x0 + 2, gy, x0 + 7, SIDEWALK_Y - 1, TRUNK[2])
    px.rect(x0 + 2, gy, x0 + 7, gy, TRUNK[0])
    if w > 26:
        px.rect(x0 + 11, gy + 1, x0 + w - 5, SIDEWALK_Y - 3, GLASS[2])
        px.rect(x0 + 11, gy + 1, x0 + w - 5, gy + 1, GLASS[0])
        if kind == "awning":
            ac = rnd.choice(CARS)
            for x in range(x0 + 9, x0 + w - 3):
                px.put(x, gy - 2, ac[0] if (x // 3) % 2 else H("#f4f0e8"))
                px.put(x, gy - 1, ac[1] if (x // 3) % 2 else H("#d8d4cc"))
                px.put(x, gy, ac[3])
    if kind == "escape":
        ex = x0 + w // 2 - 6
        y = top + 10
        while y < gy - 3:
            px.rect(ex, y, ex + 12, y, H("#2a2a32"))
            for xx in range(ex, ex + 13, 2):
                px.put(xx, y - 1, H("#3a3a44"))
            y += 9
        for yy in range(top + 10, gy - 3):
            px.put(ex + 12 - (yy % 9), yy, H("#2a2a32"))


def tree(px, cx, base, r, rnd):
    for y in range(base - r - 6, base):
        px.put(cx, y, TRUNK[1])
        px.put(cx + 1, y, TRUNK[2])
    blobs = [(cx + rnd.randint(-r // 2, r // 2), base - r - 6 + rnd.randint(-r // 3, r // 3), r * rnd.uniform(0.6, 0.85))
             for _ in range(5)] + [(cx, base - r - 8, r)]
    L = P.LIGHT
    for y in range(base - 2 * r - 12, base - 4):
        for x in range(cx - r - 4, cx + r + 5):
            best = None
            for bx, by, br in blobs:
                dx, dy = (x + 0.5 - bx) / br, (y + 0.5 - by) / br
                d2 = dx * dx + dy * dy
                if d2 < 1:
                    nz = math.sqrt(1 - d2)
                    i = -dx * L[0] * -1 * -1 + (-dy) * L[1] + nz * L[2]
                    i = dx * L[0] - dy * L[1] + nz * L[2]
                    if best is None or nz > best[0]:
                        best = (nz, i)
            if best:
                i = best[1] + rnd.uniform(-0.12, 0.12)
                k = 0 if i > 0.75 else (1 if i > 0.35 else (2 if i > -0.05 else 3))
                px.put(x, y, LEAF[k])


def car(px, x0, y_bottom, c, facing):
    """A generic boxy car seen from the side (no make or badge)."""
    w = 30
    body_top = y_bottom - 9
    for x in range(x0, x0 + w):
        for y in range(body_top, y_bottom - 2):
            k = 1 if y > body_top else 0
            if y >= y_bottom - 4:
                k = 2
            px.put(x, y, c[k])
    # cabin
    cab0 = x0 + (7 if facing > 0 else 5)
    for y in range(body_top - 6, body_top):
        sl = body_top - y
        for x in range(cab0 + sl // 2, cab0 + 18 - sl // 2):
            px.put(x, y, c[1] if y > body_top - 6 else c[0])
    for y in range(body_top - 5, body_top):
        sl = body_top - y
        for x in range(cab0 + 1 + sl // 2, cab0 + 17 - sl // 2):
            if x != cab0 + 9:
                px.put(x, y, GLASS[1] if x < cab0 + 9 else GLASS[2])
    # bumpers, lights, wheels
    px.rect(x0, y_bottom - 4, x0 + w - 1, y_bottom - 4, c[3])
    px.put(x0 + (w - 1 if facing > 0 else 0), body_top + 2, H("#fff4c0"))
    px.put(x0 + (0 if facing > 0 else w - 1), body_top + 2, H("#e0302a"))
    for wx in (x0 + 5, x0 + w - 9):
        for y in range(y_bottom - 5, y_bottom + 1):
            for x in range(wx, wx + 5):
                dx, dy = x - (wx + 2), y - (y_bottom - 2)
                if dx * dx + dy * dy <= 7:
                    px.put(x, y, H("#1c1c22") if dx * dx + dy * dy > 1 else H("#8a8a96"))
    px.rect(x0 + 2, y_bottom + 1, x0 + w - 3, y_bottom + 1, ROAD[3])    # shadow


def blacktop_backdrop(seed=8):
    rnd = random.Random(seed)
    px = Pix(BD_W, BD_H, SKY[0])
    # sky bands (dithered at the joins) and a few clouds
    for y in range(SIDEWALK_Y):
        band = min(3, y // 12)
        for x in range(BD_W):
            c = SKY[band]
            if y % 12 == 0 and band > 0 and (x + y) % 2 == 0:
                c = SKY[band - 1]
            px.put(x, y, c)
    for cx, cy, cw in ((40, 14, 22), (150, 9, 30), (260, 17, 18), (330, 11, 26)):
        for x in range(cx, cx + cw):
            hh = 2 + int(2.5 * math.sin(math.pi * (x - cx) / cw))
            for y in range(cy + 3 - hh, cy + 4):
                px.put(x, y, H("#ffffff") if y < cy + 3 else H("#d8ecf4"))
    # buildings: a block of row houses, wrapping in x
    x = 0
    kinds = ["plain", "awning", "escape", "plain", "awning", "stucco"]
    k = 0
    while x < BD_W:
        w = rnd.choice((30, 36, 42, 48))
        if BD_W - (x + w) < 30:
            w = BD_W - x            # the last building fills the rest, so the strip wraps cleanly
        top = rnd.randint(24, 42)
        building(px, x, w, top, BRICK[k % len(BRICK)], rnd, kinds[k % len(kinds)])
        x += w
        k += 1
    # far sidewalk, street, near curb and ground strip
    px.rect(0, SIDEWALK_Y, BD_W - 1, ROAD_Y - 1, CONCRETE[1])
    px.rect(0, SIDEWALK_Y, BD_W - 1, SIDEWALK_Y, CONCRETE[0])
    for x in range(0, BD_W, 12):
        px.rect(x, SIDEWALK_Y + 1, x, ROAD_Y - 2, CONCRETE[2])
    px.rect(0, ROAD_Y - 1, BD_W - 1, ROAD_Y - 1, CONCRETE[3])      # curb face
    px.rect(0, ROAD_Y, BD_W - 1, ROAD_Y1, ROAD[1])
    for _ in range(260):
        px.put(rnd.randrange(BD_W), rnd.randint(ROAD_Y, ROAD_Y1), ROAD[rnd.choice((0, 2, 3))])
    for x in range(0, BD_W, 24):                                   # dashed centre line
        px.rect(x, ROAD_Y + 8, x + 11, ROAD_Y + 8, H("#e8c440"))
    px.rect(0, ROAD_Y1 + 1, BD_W - 1, ROAD_Y1 + 1, CONCRETE[0])    # near curb top
    px.rect(0, ROAD_Y1 + 2, BD_W - 1, GROUND_Y, CONCRETE[2])
    px.rect(0, GROUND_Y + 1, BD_W - 1, BD_H - 1, H("#5a7a3a"))     # grass strip at the fence foot
    for x in range(BD_W):
        if rnd.random() < 0.5:
            px.put(x, GROUND_Y + 1, H("#7aa04a"))
        if rnd.random() < 0.3:
            px.put(x, BD_H - 1, H("#44602e"))
    # parked cars and street trees (in front of the buildings)
    for cx, ci, f in ((22, 0, 1), (138, 1, -1), (250, 3, 1), (318, 2, -1)):
        car(px, cx, ROAD_Y + 6, CARS[ci], f)
    for tx in (96, 206, 362):
        tree(px, tx, SIDEWALK_Y + 3, 11, rnd)
    # a street lamp
    for lx in (60, 284):
        px.rect(lx, 34, lx, SIDEWALK_Y + 2, H("#3a3e48"))
        px.rect(lx, 34, lx + 5, 34, H("#3a3e48"))
        px.rect(lx + 4, 35, lx + 6, 35, H("#fff0b0"))
    img = px.image()
    img = fade(img, H("#b0c4d0"), 0.18)          # distance haze
    # the chain-link fence in front: posts, rails, diamond mesh (blended so the street shows through)
    px = Pix(BD_W, BD_H, (0, 0, 0))
    px.a = np.asarray(img).copy()
    for y in range(FENCE_TOP + 2, BD_H - 2):
        for x in range(BD_W):
            u, v = (x + y) % 6, (x - y) % 6
            if u == 0 or v == 0:
                lit = u == 0
                px.blend(x, y, FENCE[1] if lit else FENCE[2], 0.55 if lit else 0.5)
    for x in range(BD_W):                                          # top rail and bottom tension wire
        px.put(x, FENCE_TOP, FENCE[0])
        px.put(x, FENCE_TOP + 1, FENCE[2])
        px.put(x, BD_H - 3, FENCE[2])
    for x in range(0, BD_W, 64):                                   # posts with caps
        px.rect(x, FENCE_TOP - 2, x + 2, BD_H - 2, FENCE[1])
        px.rect(x, FENCE_TOP - 2, x, BD_H - 2, FENCE[0])
        px.rect(x + 2, FENCE_TOP - 1, x + 2, BD_H - 2, FENCE[3])
        px.rect(x - 1, FENCE_TOP - 3, x + 3, FENCE_TOP - 2, FENCE[2])
        px.rect(x - 1, FENCE_TOP - 3, x + 2, FENCE_TOP - 3, FENCE[0])
    px.rect(0, BD_H - 2, BD_W - 1, BD_H - 1, H("#44602e"))
    return px.image()


# ============================================================================= Phase 6 city looks (P6-A2)
# Eight more looks, one per Road Trip city. Same conventions as gym/blacktop: 64 x 64 seamless floor tiles drawn as
# seen in the 3/4 view, 384 x 100 backdrops that repeat in x, bottom row on the floor. At 1280 x 720 the game shows
# about the bottom 46 rows of a backdrop (3.36 screen px per texel; the HUD bar covers the top of that), a 16:10
# screen about 24 rows more, so each city's landmark shape sits in rows ~50-95. Everything is generic: no real
# buildings, skylines, logos, brands or text.

def wave(x, period, terms):
    """A smooth curve that repeats every `period` texels: terms = [(harmonic k, amplitude, phase), ...]."""
    return sum(a * math.sin(2 * math.pi * k * x / period + p) for k, a, p in terms)


def tone4(v, cuts=(0.75, 0.45, 0.15)):
    """0..1 light value -> palette index 0 (lit) .. 3 (dark)."""
    return 0 if v > cuts[0] else (1 if v > cuts[1] else (2 if v > cuts[2] else 3))


def sky(px, y0, y1, cols):
    """Vertical bands of cols (top .. horizon), 2-row checker dither at each join."""
    n = len(cols)
    for y in range(y0, y1):
        f = (y - y0) * n / max(1, (y1 - y0))
        b = min(n - 1, int(f))
        fr = f - b
        for x in range(px.w):
            c = cols[b]
            if b > 0 and fr < 0.2 and (x + y) % 2 == 0:
                c = cols[b - 1]
            px.put(x, y, c)


def clouds(px, specs, lit, shade):
    for cx, cy, cw in specs:
        for x in range(cx, cx + cw):
            hh = 2 + int(2.5 * math.sin(math.pi * (x - cx) / cw))
            for y in range(cy + 3 - hh, cy + 4):
                px.put(x, y, lit if y < cy + 3 else shade)


def haze_rows(img, color, t_top, t_bot):
    """Blend each row toward a haze colour, t_top at row 0 .. t_bot at the bottom row (pushes the backdrop back)."""
    a = np.asarray(img).astype(float)
    h = a.shape[0]
    hz = np.array(color, float)
    for y in range(h):
        t = t_top + (t_bot - t_top) * y / (h - 1)
        a[y] = a[y] * (1 - t) + hz * t
    return Image.fromarray(np.clip(a + 0.5, 0, 255).astype(np.uint8), "RGB")


def from_img(img):
    px = Pix(img.size[0], img.size[1], (0, 0, 0))
    px.a = np.asarray(img).copy()
    return px


def crack(px, x, y, steps, rnd, c, edge=None):
    """A wandering hairline crack (wraps on tiles), mostly along x; edge: a colour on the texel below (moss, sheen)."""
    for _ in range(steps):
        px.put(x, y, c)
        if edge is not None and rnd.random() < 0.5:
            px.put(x, y + 1, edge)
        x += rnd.choice((1, 1, 1, 0, -1)) if rnd.random() < 0.3 else 1
        y += rnd.choice((-1, 0, 0, 0, 1))


def noise_tones(px, tones, seed_rnd, cells=4, fine_cells=16, cuts=(0.80, 0.48, 0.20), fine_w=0.25):
    n = periodic_noise(px.w, px.h, cells, seed_rnd, octaves=3)
    f = periodic_noise(px.w, px.h, fine_cells, seed_rnd, octaves=1)
    v = (1 - fine_w) * n + fine_w * f
    v = (v - v.min()) / (v.max() - v.min())
    for y in range(px.h):
        for x in range(px.w):
            px.put(x, y, tones[tone4(v[y, x], cuts)])
    return v


# ----------------------------------------------------------------------------- city floor tiles

DRIVE = pal("#cdc6b6", "#c1baa9", "#b4ad9c", "#a69f8e")     # barn: poured concrete driveway
DRIVE_JOINT = pal("#8c8676")                # joints and cracks (blended)
STRAW = pal("#f0d488", "#d4b060")


def barn_floor(seed=21):
    """Concrete driveway: soft blotches, a faint saw-cut joint at the tile edges (slabs about 11 x 22 ft), soft
    hairline cracks and a few bits of straw blown off the barn. Nothing high-contrast, so the tile's repeat (every
    215 screen px) doesn't show and the court lines stay the only lines."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, DRIVE[1], wrap_y=True)
    noise_tones(px, DRIVE, rnd, cuts=(0.82, 0.50, 0.22))
    for _ in range(70):                                         # sand grains in the broom finish
        px.put(rnd.randrange(TILE), rnd.randrange(TILE), DRIVE[rnd.choice((0, 3))])
    for x in range(TILE):                                       # saw-cut joints: faint, so they never read as lines
        px.blend(x, 0, DRIVE_JOINT[0], 0.35)
    for y in range(TILE):
        px.blend(0, y, DRIVE_JOINT[0], 0.25)
    for _ in range(2):                                          # hairline cracks (soft)
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        for _k in range(rnd.randint(8, 14)):
            px.blend(x, y, DRIVE_JOINT[0], 0.45)
            x += 1
            y += rnd.choice((-1, 0, 0, 1))
    for _ in range(5):                                          # straw bits: 2-3 texel diagonal strokes
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        dx = rnd.choice((1, -1))
        for k in range(rnd.randint(2, 3)):
            px.put(x + k * dx, y + (k if rnd.random() < 0.4 else 0), STRAW[k % 2])
    return px.image()


ROOFTILE = pal("#5f7a9a", "#5a7494", "#54708f", "#4e6a88")  # rooftop: modular sport tiles, slate blue
ROOFTILE_SEAM = pal("#34465e", "#7e98b6")


def rooftop_floor(seed=22):
    """Interlocking sport tiles on a roof deck: 8 x 4 texel squares (about 1.3 ft), a soft seam right and below, and a slightly different tone per tile (sun-faded ones). The joints are soft so the grid stays behind the court lines."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, ROOFTILE[1], wrap_y=True)
    for ty in range(TILE // 4):
        for tx in range(TILE // 8):
            k = rnd.choice((1, 1, 1, 2, 2, 0))
            base = ROOFTILE[k]
            for dy in range(4):
                for dx in range(8):
                    c = base
                    if dx == 7 or dy == 3:
                        c = mix(base, ROOFTILE_SEAM[0], 0.45)     # the joint between tiles, kept soft
                    px.put(tx * 8 + dx, ty * 4 + dy, c)
    for _ in range(6):                                          # a few scuffs
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        for k in range(rnd.randint(3, 5)):
            px.blend(x + k, y, H("#2c3a4c"), 0.4)
    return px.image()


OLDWOOD = pal("#cf9156", "#c1834a", "#b27540", "#a26838")    # Memphis soul gym: older, darker, redder maple
OLDWOOD_SEAM = H("#7c4626")
OLDWOOD_GRAIN = H("#9a5e32")


def soul_gym_floor(seed=23):
    """Old-school gym boards: narrower (2 texels + seam), deeper amber varnish, dull worn patches and dark sneaker
    scuffs from decades of games."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, OLDWOOD[1], wrap_y=True)
    wear = periodic_noise(TILE, TILE, 2, rnd, octaves=2)
    wear = (wear - wear.min()) / (wear.max() - wear.min())
    for r in range(TILE // 3):
        y = r * 3
        while True:
            n = rnd.choice((2, 3, 3))
            js = sorted(rnd.randrange(TILE) for _ in range(n))
            gaps = [(js[(k + 1) % n] - js[k]) % TILE for k in range(n)]
            if min(gaps) >= 10:
                break
        for k in range(n):
            x0, L = js[k], gaps[k]
            base = OLDWOOD[rnd.choice((0, 1, 1, 2, 2, 3))]
            for dx in range(L):
                x = x0 + dx
                for dy in range(2):
                    c = base
                    if dy == 0:
                        c = mix(base, (255, 228, 180), 0.12)
                    if wear[(y + dy) % TILE, x % TILE] > 0.72:
                        c = mix(c, H("#d8b48a"), 0.30)         # worn-through varnish (dull, lighter)
                    if dx == L - 1:
                        c = mix(base, OLDWOOD_SEAM, 0.6)
                    px.put(x, y + dy, c)
            for _ in range(max(1, L // 9)):
                gx = x0 + rnd.randint(1, max(1, L - 6))
                for q in range(rnd.randint(2, 5)):
                    if (gx + q - x0) % TILE < L - 1:
                        px.put(gx + q, y + 1, mix(base, OLDWOOD_GRAIN, 0.5))
        for x in range(TILE):
            px.put(x, y + 2, OLDWOOD_SEAM)
    for _ in range(7):                                          # black sneaker scuffs: short curved strokes
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        for k in range(rnd.randint(3, 6)):
            px.blend(x + k, y + (1 if k in (0, 5) else 0), H("#3a2418"), 0.55)
    return px.image()


BAYOU_ASP = pal("#535b52", "#4a524a", "#424943", "#3a413b")  # New Orleans: humid, greenish asphalt
MOSS = pal("#7a9a4a", "#55783a")


def bayou_floor(seed=24):
    """Bayou blacktop: greenish damp asphalt, darker wet blotches, cracks with moss growing in them."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, BAYOU_ASP[1], wrap_y=True)
    noise_tones(px, BAYOU_ASP, rnd)
    for _ in range(90):
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        px.put(x, y, rnd.choice((H("#727a70"), H("#646b62"), H("#2c322c"))))
    for sx, sy, n in ((6, 20, 14), (38, 48, 10)):
        crack(px, sx, sy, n, rnd, H("#30362f"), edge=MOSS[1])
    for _ in range(6):                                          # moss tufts
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        px.put(x, y, MOSS[0])
        px.put(x + 1, y, MOSS[1])
    return px.image()


PARKCOURT = pal("#6a9a64", "#5e8e58", "#54824f", "#4a7646")  # Denver: green acrylic park court, sun-bleached
PARKCOURT_CRACK = pal("#3a5a38", "#8cb684")


def mountain_floor(seed=25):
    """Mountain park court: green acrylic coat with its sandy grit, faded where the sun hits, a few patched
    hairline cracks (dark line, a lighter filler line beside it) and pine needles."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, PARKCOURT[1], wrap_y=True)
    v = periodic_noise(TILE, TILE, 3, rnd, octaves=2)
    v = (v - v.min()) / (v.max() - v.min())
    for y in range(TILE):
        for x in range(TILE):
            k = 1 if v[y, x] > 0.55 else 2
            if v[y, x] > 0.85:
                k = 0
            if rnd.random() < 0.22:                           # grit: a texel one tone off
                k = max(0, min(3, k + rnd.choice((-1, 1))))
            px.put(x, y, PARKCOURT[k])
    crack(px, 10, 22, 12, rnd, PARKCOURT[3], edge=PARKCOURT[0])
    for _ in range(3):                                          # pine needles
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        for k in range(3):
            px.put(x + k, y - (k // 2), H("#7a5a30"))
    return px.image()


WETASP = pal("#474b54", "#40444d", "#393d46", "#32363e")     # Seattle: rain-dark asphalt
SHEEN = pal("#8ea0b4", "#6c7c90", "#56647a")


def rain_park_floor(seed=26):
    """Wet park asphalt: darker than the blacktop, with the grey sky reflected as long horizontal sheen streaks
    (the light runs along the court seen from the side) and a few bright wet stones."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, WETASP[1], wrap_y=True)
    v = noise_tones(px, WETASP, rnd)
    for _ in range(70):
        px.put(rnd.randrange(TILE), rnd.randrange(TILE), rnd.choice((H("#5c606a"), H("#2a2d34"))))
    for _ in range(18):                                         # sheen streaks, on the lighter (raised, wetter) areas
        for _try in range(10):
            x, y = rnd.randrange(TILE), rnd.randrange(TILE)
            if v[y, x] > 0.45:
                break
        L = rnd.randint(4, 12)
        for k in range(L):
            t = 1 - abs(k - L / 2) / (L / 2)                  # brightest in the middle of the streak
            px.blend(x + k, y, SHEEN[0] if t > 0.6 else SHEEN[1], 0.25 + 0.45 * t)
        if L > 8:
            for k in range(2, L - 2):
                px.blend(x + k, y + 1, SHEEN[2], 0.3)
    for _ in range(12):                                         # glints
        px.put(rnd.randrange(TILE), rnd.randrange(TILE), H("#c4d0dc"))
    return px.image()


SAND = pal("#efd8a6", "#e5cb94", "#d9bc84", "#ccad74")       # Los Angeles: beach sand
SAND_BITS = pal("#fff4e0", "#f2b8a8", "#9a8a78", "#b49064")


def beach_floor(seed=27):
    """Packed beach sand: wind ripples (wavy lines along the court, foreshortened: lit crest, shaded trough),
    footprint dimples, shell bits and pebbles. Seamless: the ripples follow curves that repeat every tile."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, SAND[1], wrap_y=True)
    v = periodic_noise(TILE, TILE, 4, rnd, octaves=2)
    v = (v - v.min()) / (v.max() - v.min())
    for y in range(TILE):
        for x in range(TILE):
            ph = y + wave(x, TILE, ((1, 1.6, 0.4), (2, 0.8, 2.1))) + 2.0 * v[y, x]
            r = ph % 5.33                                       # 12 ripples per tile
            k = 1
            if r < 1.0:
                k = 0                                           # crest catches the light
            elif r < 2.0:
                k = 2                                           # lee side
            if v[y, x] > 0.8 and k == 1:
                k = 0
            if rnd.random() < 0.08:
                k = min(3, k + 1)                               # grain
            px.put(x, y, SAND[k])
    for _ in range(5):                                          # footprints: dimple pairs
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        for fx, fy in ((0, 0), (5, 2)):
            for dx in range(3):
                px.put(x + fx + dx, y + fy, SAND[3] if dx < 2 else SAND[2])
                px.put(x + fx + dx, y + fy + 1, SAND[0] if dx > 0 else SAND[2])
    for _ in range(10):
        px.put(rnd.randrange(TILE), rnd.randrange(TILE), SAND_BITS[rnd.randrange(4)])
    return px.image()


CAGEASP = pal("#5c5854", "#534f4c", "#4a4644", "#413d3b")    # New York: warm grey city asphalt
TAR = pal("#1e1c20", "#4c4a50")
PATCH = pal("#45444a", "#3c3b41")


def cage_floor(seed=28):
    """City cage asphalt: worn, soft darker repair areas and thin tar-sealed crack lines ("tar snakes")."""
    rnd = random.Random(seed)
    px = Pix(TILE, TILE, CAGEASP[1], wrap_y=True)
    noise_tones(px, CAGEASP, rnd)
    for _ in range(110):
        x, y = rnd.randrange(TILE), rnd.randrange(TILE)
        px.put(x, y, rnd.choice((H("#7a7672"), H("#6a6662"), H("#2e2b2a"))))
    patch = periodic_noise(TILE, TILE, 3, rnd, octaves=2)      # soft darker repair areas (no hard edges)
    for y in range(TILE):
        for x in range(TILE):
            if patch[y, x] > 0.66:
                px.blend(x, y, PATCH[1], 0.35)
    for sx, sy, n in ((30, 10, 18), (6, 42, 14)):              # tar snakes: 1 texel, a gloss texel here and there
        x, y = sx, sy
        for _ in range(n):
            px.blend(x, y, TAR[0], 0.7)
            if rnd.random() < 0.3:
                px.put(x, y - 1, TAR[1])
            x += 1
            y += rnd.choice((-1, 0, 0, 0, 1))
    return px.image()


